#go-hud .hud-column{width:clamp(195px,17.5vw,285px);display:flex;flex-direction:column;justify-content:space-between;gap:14px}
#go-hud .hud-card{pointer-events:auto;position:relative;display:flex;align-items:center;gap:12px;min-height:66px;padding:10px 14px;color:var(--hud-ink);text-decoration:none;border:1px solid #13bcd1a6;border-radius:11px;background:linear-gradient(125deg,#042031a1,#01111bd9);box-shadow:inset 0 1px 0 #c8f7ff05;transition:background .18s,border-color .18s,box-shadow .18s;line-height:1.5}
